insert into public.option_value (group_id, label, price, badge, is_default, is_available, sort_order)
select g.group_id, v.label, v.price, v.badge, v.is_default, v.is_available, v.sort_order
from v join public.option_group g on g.item_id = v.item_id and g.code = v.code
on conflict (group_id, label) do update set price = excluded.price, badge = excluded.badge,
  is_default = excluded.is_default, is_available = excluded.is_available, sort_order = excluded.sort_order;

